import json
from pathlib import Path
p=Path('dist');a=json.loads((p/'lessons.json').read_text())[:18]
for l in a:l['category']='algorithms'
# Original compact exercises and explanations; quizzes test the concept shown.
rows=[
('python','Variables & types','Foundation','Python names refer to objects. Integers, floats, strings and booleans represent different kinds of values. Convert explicitly when reading numeric text.','age = int("30")\nprint(age + 1)  # 31','What is int("3") + 2?',['5','32','An error'],0,'O(1) for these fixed-size examples','Convert and add','Convert two numeric strings to integers and return their sum. Example: "12", "8" → 20.'),
('python','Conditions & loops','Foundation','Use if to choose a branch and for to visit a sequence. range(n) yields 0 through n-1. Track a variable whose meaning stays clear after every iteration.','def count_even(nums):\n    count = 0\n    for x in nums:\n        if x % 2 == 0:\n            count += 1\n    return count','Which values are in range(3)?',['1,2,3','0,1,2','0,1,2,3'],1,'O(n) time, O(1) space','Count even numbers','Return how many even numbers a list contains. Example: [2,3,4] → 2. Test an empty list.'),
('python','Functions & scope','Foundation','Functions isolate reusable work. return sends a value to the caller; print only displays it. Prefer parameters over changing global state.','def square(x):\n    return x * x\n\nresult = square(4)  # 16','Which sends a result to the caller?',['print','return','input'],1,'O(1) for fixed-size integers','Build a reusable function','Write a function clamp(x, low, high) that returns x restricted to the inclusive bounds. Example: clamp(12,0,10) → 10.'),
('python','Dictionaries & counting','Core','A dictionary maps keys to values. get(key, default) helps count new keys without a separate branch. Dictionary lookup is average constant time.','def frequency(words):\n    counts = {}\n    for word in words:\n        counts[word] = counts.get(word, 0) + 1\n    return counts','What does get("new", 0) return for a missing key?',['None','0','An error'],1,'O(n) average time, O(u) distinct keys','Word frequency','Count words in a list. Example: ["cat","dog","cat"] → {"cat":2,"dog":1}.'),
('python','Exceptions & input validation','Core','Raise an exception when a function receives invalid input. Catch specific expected exceptions at a boundary where you can recover; avoid hiding unexpected errors.','def reciprocal(x):\n    if x == 0:\n        raise ValueError("x must be nonzero")\n    return 1 / x','Which input must this function reject?',['2','-1','0'],2,'O(1) time and space','Validate a score','Write validate_score(x), accepting integers from 0 to 100 and raising ValueError otherwise. Decide explicitly whether bool should be accepted.'),
('structures','Strings & character counts','Foundation','Strings are immutable sequences. Count characters with a map. State whether comparison is case-sensitive and whether spaces count.','def char_counts(s):\n    counts = {}\n    for c in s:\n        counts[c] = counts.get(c, 0) + 1\n    return counts','Can you assign s[0] = "a" on a Python string?',['Yes','No','Only for short strings'],1,'O(n) time, O(u) space','Valid Anagram','valid-anagram'),
('structures','Stacks & brackets','Core','A stack follows last in, first out. For balanced brackets, push opening brackets and match each closing bracket to the latest opening bracket.','stack = []\nstack.append("(")\nprint(stack.pop())  # (','Which item leaves a stack first?',['Oldest','Newest','Smallest'],1,'O(n) time and O(n) space for bracket matching','Valid Parentheses','valid-parentheses'),
('structures','Queues & breadth-first search','Core','A queue follows first in, first out. Breadth-first search explores an unweighted graph in layers. Mark nodes when enqueuing to avoid duplicates.','from collections import deque\nq = deque(["start"])\nq.append("next")\nprint(q.popleft())  # start','BFS finds shortest paths when edges have…',['Equal weight','Any negative weight','Arbitrary unequal weight'],0,'O(V+E) traversal time, O(V) space','Binary Tree Level Order Traversal','binary-tree-level-order-traversal'),
('structures','Linked lists & pointers','Core','A linked list stores nodes connected by references. Save the next reference before reversing a link, or you can lose the rest of the list.','def reverse(head):\n    previous = None\n    while head:\n        following = head.next\n        head.next = previous\n        previous, head = head, following\n    return previous','Before overwriting next, save…',['The next node','The list length','The last value'],0,'O(n) time, O(1) extra space','Reverse Linked List','reverse-linked-list'),
('structures','Trees & depth-first search','Core','Recursion solves the left and right subtrees. A base case handles an empty node. Recursion uses stack space proportional to tree height.','def depth(node):\n    if node is None:\n        return 0\n    return 1 + max(depth(node.left), depth(node.right))','Depth of an empty tree in this definition?',['0','1','-1'],0,'O(n) time, O(h) stack space','Maximum Depth of Binary Tree','maximum-depth-of-binary-tree'),
('structures','Graphs & visited sets','Advanced','Graphs represent relationships. A visited set prevents repeatedly processing nodes in cycles. DFS can count connected components by starting from every unvisited node.','def reachable(graph, start):\n    seen, stack = set(), [start]\n    while stack:\n        node = stack.pop()\n        if node in seen:\n            continue\n        seen.add(node)\n        stack.extend(graph.get(node, []))\n    return seen','What prevents infinite traversal around a cycle?',['Sorting','A visited set','A larger stack'],1,'O(V+E) time, O(V) space','Find reachable nodes','Implement reachable nodes for an adjacency-list graph. Include a cycle, isolated node and disconnected component in your tests.'),
('structures','Heaps & top k','Advanced','A min-heap exposes the smallest value. To retain the k largest values, keep a min-heap of size k and discard its smallest value when the size grows.','import heapq\n\ndef top_k(nums, k):\n    if k < 0:\n        raise ValueError("negative k")\n    return heapq.nlargest(k, nums)','A size-k min-heap for the largest k values exposes…',['Largest retained value','Smallest retained value','Median'],1,'O(n log k) typical for 1 < k < n; O(k) output space','Kth Largest Element in an Array','kth-largest-element-in-an-array'),
('math','Remainders & divisibility','Foundation','a % b gives a remainder. For positive b, the result is between 0 and b-1. A number is divisible by b when its remainder is zero.','def divisible(n, d):\n    if d == 0:\n        raise ValueError("zero divisor")\n    return n % d == 0','17 % 5 equals…',['2','3','5'],0,'O(1) for fixed-size integers','Fizz Buzz','fizz-buzz'),
('math','Digits & integer arithmetic','Foundation','Extract a nonnegative integer’s last digit with n % 10. Remove it with n // 10. Handle zero explicitly when counting digits.','def digit_sum(n):\n    n = abs(n)\n    total = 0\n    while n:\n        total += n % 10\n        n //= 10\n    return total','Last digit of 327 is…',['3','2','7'],2,'O(d) time for d digits, O(1) space','Sum the digits','Return the digit sum of an integer, ignoring its sign. Examples: -327 → 12; 0 → 0.'),
('math','GCD & Euclid','Core','The greatest common divisor satisfies gcd(a,b) = gcd(b,a % b). Repeatedly reduce until the second value is zero. Normalize signs first.','def gcd(a, b):\n    a, b = abs(a), abs(b)\n    while b:\n        a, b = b, a % b\n    return a','gcd(18,12) equals…',['3','6','12'],1,'O(log min(a,b)) divisions for positive inputs','Implement GCD and LCM','Implement gcd and lcm. Define lcm as 0 if either input is 0; otherwise abs(a // gcd(a,b) * b).'),
('math','Prime numbers','Core','A prime has exactly two positive divisors. If n is composite, at least one factor is at most its square root. Values below two are not prime.','def is_prime(n):\n    if n < 2:\n        return False\n    d = 2\n    while d*d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return True','Is 1 prime?',['Yes','No','Only in Python'],1,'O(√n) time, O(1) space','Prime checker','Implement is_prime and test -1, 0, 1, 2, 9 and 17. Then explain how a sieve improves many prime queries.'),
('math','Probability & conditional events','Core','Conditional probability changes the sample space: P(A given B) = P(A and B) / P(B), provided P(B) > 0. Independence is an assumption you must justify.','def conditional(p_joint, p_condition):\n    if not 0 < p_condition <= 1 or not 0 <= p_joint <= p_condition:\n        raise ValueError("invalid probabilities")\n    return p_joint / p_condition','P(A and B)=0.2, P(B)=0.5. P(A given B)?',['0.1','0.4','0.7'],1,'O(1) time and space','Conditional probability drill','A fair die is rolled. Given an even result, what is the probability of a result above 3? List the conditional sample space before calculating.'),
('math','Vectors & dot products','Core','The dot product sums pairwise products of equal-length vectors. In a linear model, it combines features and weights before adding a bias.','def dot(a, b):\n    if len(a) != len(b):\n        raise ValueError("shape mismatch")\n    return sum(x*y for x,y in zip(a,b))','Dot product of [1,2] and [3,4]?',['7','11','14'],1,'O(d) time, O(1) extra space','Implement a linear prediction','Write predict(features, weights, bias). Reject shape mismatch. Example: [1,2], [3,4], 1 → 12.'),
('math','Derivatives & optimization','Advanced','A derivative measures local rate of change. Gradient descent moves opposite the gradient to reduce a smooth objective, with a suitable learning rate.','x = 4.0\nlearning_rate = 0.1\nfor _ in range(20):\n    gradient = 2*x  # derivative of x squared\n    x -= learning_rate * gradient','Derivative of x² is…',['x','2x','2'],1,'O(t) for t iterations','Minimize a quadratic','Minimize (x-3)² with gradient descent. Derive its gradient first. Compare learning rates 0.1 and 1.1 and explain the behavior.'),
('ml','Train, validation & test','Foundation','Fit parameters on training data. Use validation data for model selection. Keep the test set untouched until final evaluation. Split related records together to prevent leakage.','# Example split sizes, not a randomization strategy\nn = 1000\ntrain_end, val_end = 700, 850\nprint(train_end, val_end-train_end, n-val_end)','Which split is used for final unbiased assessment?',['Training','Validation','Held-out test'],2,'Depends on the dataset and model','Design a leakage-safe split','For EEG windows from multiple patients, propose a patient-separated split. Explain why randomly splitting overlapping windows can inflate results.'),
('ml','Regression & squared error','Core','Regression predicts continuous targets. Mean squared error averages squared residuals and penalizes large errors strongly. Compare against a simple baseline.','def mse(y, pred):\n    if not y or len(y) != len(pred):\n        raise ValueError("invalid shapes")\n    return sum((a-b)**2 for a,b in zip(y,pred))/len(y)','MSE for [1,3] versus [2,2]?',['0','1','2'],1,'O(n) time, O(1) space','Implement MSE','Implement MSE and MAE without libraries. Explain which reacts more strongly to a single very large error.'),
('ml','Classification metrics','Core','Precision asks how many predicted positives were correct. Recall asks how many actual positives were found. F1 is their harmonic mean. Accuracy can mislead on imbalanced labels.','def precision_recall(tp, fp, fn):\n    precision = tp/(tp+fp) if tp+fp else 0.0\n    recall = tp/(tp+fn) if tp+fn else 0.0\n    return precision, recall','Recall is…',['TP/(TP+FP)','TP/(TP+FN)','TN/(TN+FP)'],1,'O(1) from confusion counts','Evaluate a spindle detector','For TP=30, FP=10, FN=20, calculate precision, recall and F1. State your policy for a zero denominator.'),
('ml','Overfitting & regularization','Core','A model may memorize training noise and fail on unseen data. Compare training and validation curves. Regularization, simpler models and better data can help; evaluate changes on validation data.','# L2 penalty for weights\nweights = [2.0, -1.0]\npenalty = 0.01 * sum(w*w for w in weights)\nprint(penalty)  # 0.05','Low training error and high validation error suggests…',['Overfitting','Guaranteed success','No learning'],0,'O(d) to calculate a penalty for d weights','Diagnose learning curves','Training loss decreases while validation loss rises after epoch 8. Propose early stopping and two other experiments. Keep the test set untouched.'),
('ml','Features, scaling & pipelines','Core','Fit preprocessing statistics on training data only. Apply those same statistics to validation and test data. Keep preprocessing and the model together in a reproducible pipeline.','def standardize(values, mean, std):\n    if std <= 0:\n        raise ValueError("std must be positive")\n    return [(x-mean)/std for x in values]','Fit a scaler on…',['All data before splitting','Training data only','Test data only'],1,'O(n) for n scalar values','Prevent preprocessing leakage','Describe a pipeline for numeric features with missing values: split, fit imputation, fit scaling, train, validate. Explain where cross-validation fits.'),
('ml','Neural networks & gradients','Advanced','A neural network composes differentiable operations. Backpropagation calculates gradients; an optimizer updates parameters. Clear accumulated gradients appropriately between optimization steps.','# One scalar neuron and squared-error gradient\nx, w, target = 2.0, 0.5, 3.0\npred = w*x\ngrad_w = 2*(pred-target)*x\nw -= 0.01*grad_w','Backpropagation primarily computes…',['Gradients','New labels','The train-test split'],0,'Depends on network size and batch size','Derive a one-neuron update','For y_hat=w*x+b and loss=(y_hat-y)², derive gradients for w and b. Implement one update and verify loss decreases for a small step.'),
('ml','Experiment design & error analysis','Advanced','Record dataset version, split, seed, configuration and metrics. Compare one clear change at a time. Inspect false positives and negatives and evaluate relevant subgroups.','experiment = {\n    "seed": 42,\n    "split": "patient-separated-v1",\n    "metric": "PR-AUC",\n    "threshold_source": "validation"\n}','Choose a classification threshold using…',['The final test set repeatedly','Validation data','Only training accuracy'],1,'Depends on experiment design','Plan an ML comparison','Compare a baseline and a new model for rare-event detection. Specify the split, primary metric, threshold selection and an error-analysis table.'),
('ai','AI, ML & generative models','Foundation','AI is a broad field of systems performing tasks associated with intelligence. ML learns patterns from data. Generative models produce new outputs; fluency alone does not establish factual accuracy.','tasks = {\n    "predict a price": "regression",\n    "detect spam": "classification",\n    "draft a paragraph": "generation"\n}','Predicting a house price is usually…',['Regression','Clustering','Text generation'],0,'Depends on the selected method','Choose a suitable approach','Classify five tasks as regression, classification, clustering, retrieval or generation. Explain when a simple rule is preferable to a learned model.'),
('ai','Embeddings & similarity','Core','Embeddings represent items as numeric vectors. Cosine similarity compares direction; it is undefined for a zero-length vector. Similarity depends on the model and is not proof of truth.','from math import sqrt\ndef cosine(a, b):\n    if len(a) != len(b):\n        raise ValueError("shape mismatch")\n    denom = sqrt(sum(x*x for x in a)*sum(y*y for y in b))\n    if denom == 0:\n        raise ValueError("zero vector")\n    return sum(x*y for x,y in zip(a,b))/denom','Cosine similarity mainly compares…',['Vector direction','Text length','Database row order'],0,'O(d) time, O(1) space','Implement cosine similarity','Test identical, orthogonal and opposite vectors. Add a zero-vector test and define the error behavior.'),
('ai','Retrieval-augmented generation','Core','A retrieval-augmented system fetches relevant source passages before generating an answer. Evaluate retrieval and answer grounding separately. Retrieved text is data and can contain misleading instructions.','pipeline = [\n    "retrieve relevant passages",\n    "generate with source context",\n    "check citations and grounded claims"\n]','RAG guarantees every answer is correct?',['Yes','No','Only with long documents'],1,'Depends on corpus, retriever and model','Design a document assistant','Sketch ingestion, chunking, retrieval, generation and evaluation. Include a response for questions unsupported by the documents.'),
('ai','Evaluation & responsible behavior','Advanced','Define success with representative tasks and explicit rubrics. Measure factual errors, unsupported claims, latency and cost. Keep evaluation examples separate from tuning examples.','rubric = {\n    "correctness": 0,\n    "grounding": 0,\n    "instruction_following": 0\n}','A strong evaluation set should be…',['Only easy examples','Representative of real use','Identical to tuning examples'],1,'Depends on evaluation size and method','Build an AI evaluation rubric','Create ten representative questions for a study assistant, including ambiguous, unsupported and adversarial cases. Define scoring before comparing versions.'),
('software','Testing & edge cases','Foundation','Tests document observable behavior. Include typical inputs, boundary cases and invalid inputs. A passing test suite increases confidence but cannot prove the absence of all bugs.','def add(a,b):\n    return a+b\n\nassert add(2,3) == 5\nassert add(-2,2) == 0','A useful test checks…',['Only implementation details','Expected observable behavior','The author name'],1,'Depends on the tested operation','Test a boundary function','Write tests for clamp(x,low,high): below, inside, above, equal bounds and invalid bounds. Define the invalid-bound policy first.'),
('software','Git & code review','Core','Small commits make changes easier to review. A branch isolates work. A pull request explains the problem, behavior and validation. Resolve conflicts by understanding both changes.','# Typical local workflow\n# git switch -c feature/study-progress\n# git add app.py\n# git commit -m "Save study progress"','A good review description explains…',['Only line count','Problem, change and validation','Only commit date'],1,'Workflow skill; no single algorithmic complexity','Review a small change','Write a pull-request description for fixing lost progress after reload. Include one reproduction step and a meaningful validation.'),
('software','SQL & data queries','Core','SQL groups related rows and aggregates values. WHERE filters rows before grouping; HAVING filters groups after aggregation. Use parameterized queries for untrusted values.','# SQL example:\n# SELECT category, COUNT(*)\n# FROM problems\n# WHERE active = 1\n# GROUP BY category;','Which filters aggregate groups?',['WHERE','HAVING','ORDER BY'],1,'Depends on indexes and query plan','Count completed problems','Given attempts(user_id, problem_id, passed), write a query counting distinct passed problems per user. Explain why COUNT(*) may overcount.'),
('software','APIs & failure handling','Core','An API defines a contract between components. Validate inputs and return consistent errors. A timeout is not proof that a remote mutation failed; retries require attention to idempotency.','def validate_limit(limit):\n    if not isinstance(limit, int) or not 1 <= limit <= 100:\n        raise ValueError("limit must be 1..100")\n    return limit','Retrying a payment safely usually requires…',['Ignoring duplicates','Idempotency handling','A shorter variable name'],1,'Depends on the service and operation','Design a progress API','Specify GET progress and PUT progress contracts. Include validation, authentication, version conflicts and duplicate-request behavior.'),
('software','System design fundamentals','Advanced','Start with requirements and scale assumptions. Define data, interfaces and bottlenecks before selecting infrastructure. Explain tradeoffs in consistency, availability, latency and operational complexity.','requirements = {\n    "users": 10000,\n    "progress_sync": True,\n    "offline_reading": True,\n    "sensitive_data": "minimal"\n}','First step in a design interview?',['Choose a database immediately','Clarify requirements','Draw every server'],1,'Reasoning skill; quantify assumptions','Design a learning app','Design progress sync for a study app. Address local edits, account login, conflict resolution, backups and failures. Explain what you would simplify for 100 users.'),
('interview','Explain your reasoning','Foundation','Clarify the input and output, work through an example, state a simple approach, then improve it. Explain an invariant and analyze time and space before testing edge cases.','checklist = [\n    "clarify", "example", "baseline",\n    "improve", "code", "test", "analyze"\n]','Before coding, you should…',['Assume all constraints','Clarify requirements','Memorize variable names'],1,'Communication practice','Two Sum mock interview','Explain Two Sum aloud in five minutes. Cover duplicates, whether an answer exists, brute force, the hash-map approach and complexity.'),
('interview','Behavioral stories & projects','Core','Use a specific situation, your task, your actions and the result. Distinguish your own contribution from team work. Report outcomes honestly and explain what you learned.','story = {\n    "situation": "", "task": "",\n    "action": "", "result": "",\n    "learning": ""\n}','A strong project answer includes…',['Invented impact','Your specific actions and evidence','Only technology names'],1,'Communication practice','Tell your research story','Explain your EEG detection project in two minutes: goal, data, leakage prevention, baseline, metric, failure, improvement and what you would do next.'),
('interview','Timed practice & exam review','Advanced','Practice under a time limit after learning the concepts. Review mistakes by cause: misunderstanding, missing knowledge, implementation or time management. Retest weak skills after a delay.','review_log = {\n    "problem": "", "mistake_type": "",\n    "lesson": "", "next_practice": ""\n}','After a failed mock, the best next step is…',['Repeat blindly','Analyze mistakes and retest weak skills','Stop studying'],1,'Study-planning skill','Run a 30-minute mock','Spend 5 minutes clarifying, 15 solving, 5 testing and 5 explaining complexity. Afterwards write one concrete improvement and schedule a retry.')]
for cat,title,level,lesson,code,q,opts,ans,cost,problem,task in rows:
 linked=task and ' ' not in task and cat=='structures'
 a.append(dict(category=cat,title=title,level=level,lesson=lesson,code=code,question=q,options=opts,answer=ans,complexity=cost,problem=problem,slug=task if linked else '',task='' if linked else task))
(p/'lessons.json').write_text(json.dumps(a))
print(len(a),'learning units')
